(function() {
    var nl = document.getElementById('nlContent');
    if (nl) {
      var obs = new IntersectionObserver(function(entries) {
        if (entries[0].isIntersecting) {
          nl.classList.remove('nl-hidden');
          nl.classList.add('nl-visible');
          var el = document.getElementById('nlCounter');
          var target = 500; var current = 0; var step = Math.ceil(target / 40);
          var t = setInterval(function() {
            current = Math.min(current + step, target);
            if (el) el.textContent = current;
            if (current >= target) clearInterval(t);
          }, 40);
          obs.disconnect();
        }
      }, { threshold: 0.3 });
      obs.observe(nl);
    }
  })();

(function() {
  var params = new URLSearchParams(window.location.search);
  if (params.get('subscribed') !== '1') return;
  var toast = document.createElement('div');
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  toast.style.cssText = 'position:fixed;left:20px;right:20px;bottom:20px;max-width:720px;margin:0 auto;background:#145960;color:#fff;border-radius:14px;padding:12px 44px 12px 14px;box-shadow:0 10px 28px rgba(20,89,96,0.32);z-index:2500;font-size:14px;line-height:1.55;';
  toast.innerHTML = 'נרשמת בהצלחה! תודה שהצטרפת לקהילת "מתי טסים" ✈️ איזה כיף שאתם איתנו! מעכשיו, כל מה שצריך לטיול משפחתי מושלם יגיע אליכם למייל: עדכונים על יעדים חדשים, טיפים פרקטיים לחיסכון בזמן וכסף, ומסלולים מפורטים שיסגרו לכם את הפינה של התכנון.';

  var closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.setAttribute('aria-label', 'סגור הודעה');
  closeBtn.textContent = '×';
  closeBtn.style.cssText = 'position:absolute;left:12px;top:8px;color:#fff;background:none;border:none;font-size:24px;line-height:1;cursor:pointer;';
  toast.appendChild(closeBtn);
  document.body.appendChild(toast);

  var timer = setTimeout(hideToast, 6000);
  function hideToast() {
    if (toast && toast.parentNode) toast.parentNode.removeChild(toast);
    clearTimeout(timer);
  }
  closeBtn.addEventListener('click', hideToast);

  params.delete('subscribed');
  var cleanQuery = params.toString();
  var cleanUrl = window.location.pathname + (cleanQuery ? '?' + cleanQuery : '') + window.location.hash;
  window.history.replaceState({}, document.title, cleanUrl);
})();
